        /// <summary>lanczosVectors (allocating, Allocator) over a BSR matrix with default breakdownTol.</summary>
        public static floatN lanczosVectors(in floatBSR A, int steps, out floatMxN ritz, out LanczosInfo info, Allocator allocator = Allocator.Temp)
            => lanczosVectors(in A, steps, out ritz, out info, Consts.floatZeroThreshold, allocator);

        /// <summary>
        /// Full symmetric eigendecomposition via classical two-sided (cyclic) Jacobi iteration.
        /// Computes A = V * diag(eigenvalues) * V^T where V is orthonormal.
        ///
        /// On input: A must be square and symmetric. On output: A is DESTROYED (driven to
        /// approximately diagonal); eigenvalues (length n) holds the eigenvalues;
        /// V (n x n) holds the eigenvectors as columns (V is overwritten and initialized
        /// to the identity internally).
        ///
        /// Eigenvalues are sorted in DESCENDING ORDER BY VALUE (not magnitude), so
        /// lambda[0] &gt;= lambda[1] &gt;= ... &gt;= lambda[n-1]. This means negative eigenvalues
        /// appear last. The corresponding eigenvector columns of V are reordered to match.
        ///
        /// Returns an <see cref="EigenInfo"/> (implicit-bool == Converged): Converged if a sweep with
        /// zero Jacobi rotations was reached within maxSweeps, MaxIterations if the sweep limit was
        /// exhausted. sweeps is the number of full-matrix Jacobi sweeps consumed (all-or-nothing:
        /// converged is n on Converged, 0 on MaxIterations -- this solver does not resolve individual
        /// eigenvalues independently the way the QR/QL-based solvers do).
        ///
        /// Notes:
        ///   - Works for any real symmetric matrix including indefinite ones; eigenvalues
        ///     are always real.
        ///   - For positive semi-definite matrices the result matches SVD up to column
        ///     sign differences.
        ///   - Does not allocate.
        /// </summary>
        /// <param name="A">On entry A (must be symmetric); destroyed; contents undefined after
        /// return (driven to approximately diagonal internally, but that is not a documented
        /// usable factor -- read <paramref name="eigenvalues"/> instead).</param>
        [System.Obsolete("Prefer Eigen.symmetricInPlace (Householder tridiagonal + QL) for symmetric eigenpairs, or Eigen.valuesSymmetricInPlace for eigenvalues only. This cyclic-Jacobi solver is retained for reference.", false)]
        public static EigenInfo decompInPlace(ref floatMxN A, ref floatN eigenvalues,
                                              ref floatMxN V, int maxSweeps, float tol)
        {
            if (!A.IsSquare)
                throw new ArgumentException("Eigen.decompInPlace: A must be square");

            int n = A.N_Cols;

            if (eigenvalues.N != n)
                throw new ArgumentException("Eigen.decompInPlace: eigenvalues.N must equal A dimension");

            if (!V.IsSquare || V.M_Rows != n)
                throw new ArgumentException("Eigen.decompInPlace: V must be square with side equal to A dimension");

            if (maxSweeps < 1)
                throw new ArgumentException("Eigen.decompInPlace: maxSweeps must be >= 1");

            if (tol <= (float)0)
                throw new ArgumentException("Eigen.decompInPlace: tol must be > 0");

            // Symmetry guard: check that A is symmetric within relative tolerance
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    float aij = A[i, j];
                    float aji = A[j, i];
                    float diff = math.abs(aij - aji);
                    float relScale = (float)1 + math.abs(aij) + math.abs(aji);
                    if (diff > tol * relScale)
                        throw new ArgumentException("Eigen.decompInPlace: Matrix must be symmetric");
                }
            }

            if (n == 0)
                return new EigenInfo { status = IterativeSolveStatus.Converged, sweeps = 0, converged = 0 };

            // Initialize V to identity
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    V[i, j] = (i == j) ? (float)1 : (float)0;

            bool converged = false;
            int sweepsUsed = maxSweeps;

            for (int sweep = 0; sweep < maxSweeps; sweep++) {

                int rotations = 0;

                for (int p = 0; p < n - 1; p++) {
                    for (int q = p + 1; q < n; q++) {

                        float apq = A[p, q];

                        // Skip exact zeros
                        if (apq == (float)0)
                            continue;

                        // Skip when off-diagonal is negligible relative to the diagonal
                        if (math.abs(apq) <= tol * (float)0.5 * (math.abs(A[p, p]) + math.abs(A[q, q])))
                            continue;

                        // Compute rotation angle: theta = (A[q,q] - A[p,p]) / (2 * A[p,q])
                        float theta = (A[q, q] - A[p, p]) / ((float)2 * apq);

                        // sign(theta) with 0 -> +1
                        float signTheta = theta >= (float)0 ? (float)1 : (float)(-1);
                        float absTheta = math.abs(theta);

                        float t;
                        if (absTheta > (float)1) {
                            // Factor out |theta| to avoid theta*theta overflow
                            float inv = (float)1 / theta;
                            t = signTheta / (absTheta * ((float)1 + math.sqrt((float)1 + inv * inv)));
                        } else {
                            // |theta| <= 1 -> theta*theta <= 1, safe
                            t = signTheta / (absTheta + math.sqrt((float)1 + theta * theta));
                        }

                        float c = (float)1 / math.sqrt((float)1 + t * t);
                        float s = t * c;

                        // Apply symmetric rotation to A
                        float app = A[p, p];
                        float aqq = A[q, q];
                        A[p, p] = app - t * apq;
                        A[q, q] = aqq + t * apq;
                        A[p, q] = (float)0;
                        A[q, p] = (float)0;

                        for (int i = 0; i < n; i++) {
                            if (i == p || i == q)
                                continue;
                            float aip = A[i, p];
                            float aiq = A[i, q];
                            float newAip = c * aip - s * aiq;
                            float newAiq = s * aip + c * aiq;
                            A[i, p] = newAip;
                            A[p, i] = newAip;
                            A[i, q] = newAiq;
                            A[q, i] = newAiq;
                        }

                        // Rotate columns p and q of V
                        for (int i = 0; i < n; i++) {
                            float vip = V[i, p];
                            float viq = V[i, q];
                            V[i, p] = c * vip - s * viq;
                            V[i, q] = s * vip + c * viq;
                        }

                        rotations++;
                    }
                }

                if (rotations == 0) {
                    converged = true;
                    sweepsUsed = sweep + 1;
                    break;
                }
            }

            // Extract diagonal of (now approximately diagonal) A into eigenvalues
            for (int i = 0; i < n; i++)
                eigenvalues[i] = A[i, i];

            // Selection sort: descending by value (not magnitude)
            for (int j = 0; j < n; j++) {
                int maxIdx = j;
                float maxVal = eigenvalues[j];

                for (int k = j + 1; k < n; k++) {
                    if (eigenvalues[k] > maxVal) {
                        maxIdx = k;
                        maxVal = eigenvalues[k];
                    }
                }

                if (maxIdx != j) {
                    // Swap eigenvalues
                    float tmp = eigenvalues[j];
                    eigenvalues[j] = eigenvalues[maxIdx];
                    eigenvalues[maxIdx] = tmp;

                    // Swap corresponding columns of V only (A's diagonal traveled into eigenvalues)
                    Swap.Columns(ref V, j, maxIdx);
                }
            }

            return new EigenInfo
            {
                status = converged ? IterativeSolveStatus.Converged : IterativeSolveStatus.MaxIterations,
                sweeps = sweepsUsed,
                converged = converged ? n : 0
            };
        }

        // The default-argument overloads forward to the deprecated primitive; suppress the
        // self-referential obsolete warning (618) on the forwarding calls.
#pragma warning disable 618
        /// <summary>decompInPlace with default tol (Consts.floatZeroThreshold).</summary>
        [System.Obsolete("Prefer Eigen.symmetricInPlace (Householder tridiagonal + QL) for symmetric eigenpairs, or Eigen.valuesSymmetricInPlace for eigenvalues only. This cyclic-Jacobi solver is retained for reference.", false)]
        public static EigenInfo decompInPlace(ref floatMxN A, ref floatN eigenvalues,
                                              ref floatMxN V, int maxSweeps)
            => decompInPlace(ref A, ref eigenvalues, ref V, maxSweeps, Consts.floatZeroThreshold);

        /// <summary>decompInPlace with default maxSweeps (30) and tol (Consts.floatZeroThreshold). NOTE:
        /// this constant is NOT scaled by Consts.sweepBudget like the other Eigen/SVD defaults --
        /// decompInPlace's "sweep" is a FULL-MATRIX Jacobi sweep (O(n^2) rotations each), a
        /// fundamentally different iteration unit from the per-value QR/QL sweeps the LAPACK dbdsqr
        /// scaling targets; classical Jacobi converges in a small constant number of sweeps essentially
        /// independent of n. Also deprecated/reference-only.</summary>
        [System.Obsolete("Prefer Eigen.symmetricInPlace (Householder tridiagonal + QL) for symmetric eigenpairs, or Eigen.valuesSymmetricInPlace for eigenvalues only. This cyclic-Jacobi solver is retained for reference.", false)]
        public static EigenInfo decompInPlace(ref floatMxN A, ref floatN eigenvalues,
                                              ref floatMxN V)
            => decompInPlace(ref A, ref eigenvalues, ref V, 30, Consts.floatZeroThreshold);
#pragma warning restore 618

        /// <summary>
        /// All eigenVALUES of a SYMMETRIC real matrix, via Householder tridiagonalization followed by
        /// the implicit-shift QL iteration (EISPACK tred1 + tql1, GVL Alg. 8.3.1). Much faster than the
        /// cyclic-Jacobi decompInPlace: the O(n^3) reduction is a sequence of gemv + symmetric
        /// rank-2 updates (the rank-2 update is axpy → vectorises), and the QL sweep that follows is
        /// only O(n^2). No eigenvectors (use decompInPlace if you need them).
        ///
        /// A must be symmetric (checked within relative tolerance) and is DESTROYED. On output
        /// eigenvalues[i] holds the i-th eigenvalue, sorted DESCENDING. Returns an
        /// <see cref="EigenInfo"/> (implicit-bool == Converged); MaxIterations if QL hit
        /// maxIterPerEig for some eigenvalue (outputs then undefined). Does not allocate
        /// beyond three length-n Temp scratch vectors.
        /// </summary>
        public static EigenInfo valuesSymmetricInPlace(ref floatMxN A, ref floatN eigenvalues, int maxIterPerEig, float tol,
                                                 ref floatEigenSymCache ws)
        {
            if (!A.IsSquare)
                throw new ArgumentException("Eigen.valuesSymmetricInPlace: A must be square");

            int n = A.M_Rows;

            if (eigenvalues.N != n)
                throw new ArgumentException("Eigen.valuesSymmetricInPlace: eigenvalues.N must equal A dimension");

            if (maxIterPerEig < 1)
                throw new ArgumentException("Eigen.valuesSymmetricInPlace: maxIterPerEig must be >= 1");

            if (tol <= (float)0)
                throw new ArgumentException("Eigen.valuesSymmetricInPlace: tol must be > 0");

            // Symmetry guard (same as decompInPlace). The reduction reads the full symmetric
            // matrix (the gemv uses whole rows), so both triangles must agree.
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++)
                {
                    float aij = A[i, j], aji = A[j, i];
                    float diff = math.abs(aij - aji);
                    float relScale = (float)1 + math.abs(aij) + math.abs(aji);
                    if (diff > tol * relScale)
                        throw new ArgumentException("Eigen.valuesSymmetricInPlace: Matrix must be symmetric");
                }

            RequireEigenSymWorkspace(in ws, n);

            if (n == 0) return new EigenInfo { status = IterativeSolveStatus.Converged, sweeps = 0, converged = 0 };
            if (n == 1) { eigenvalues[0] = A[0, 0]; return new EigenInfo { status = IterativeSolveStatus.Converged, sweeps = 0, converged = 1 }; }

            var eVec = ws.eVec;   // off-diagonal e[i] couples d[i], d[i+1]
            var vVec = ws.vVec;   // Householder vector (entries m0..n-1)
            var pVec = ws.pVec;   // p = beta*A*v, then q = p - K v

            unsafe
            {
                float* ap = A.Data.Ptr;
                float* v  = vVec.Data.Ptr;
                float* p  = pVec.Data.Ptr;

                // Matrix scale (max |entry|) for the column-deflation test in the reduction below.
                float matScale = (float)0;
                for (long ii = 0; ii < (long)n * n; ii++)
                {
                    float a = math.abs(ap[ii]);
                    matScale = math.max(matScale, a);
                }
                float belowNormTol = (float)n * Consts.floatEpsilon * matScale;

                // ---- Householder tridiagonalization (full symmetric storage, values only) ----
                // The trailing submatrix stays symmetric; column k below the subdiagonal is never read
                // again, so (values-only) we record the subdiagonal in e[k] and skip zeroing it.
                for (int k = 0; k < n - 2; k++)
                {
                    int m0 = k + 1;

                    // x = A[m0.., k]; sigma = ||x[1..]||^2 (entries strictly below the leading one).
                    float sigma = 0;
                    for (int i = m0 + 1; i < n; i++)
                    {
                        float aik = ap[(long)i * n + k];
                        sigma += aik * aik;
                    }
                    float x0 = ap[(long)m0 * n + k];

                    // Deflate a column whose below-subdiagonal norm is negligible vs the matrix scale.
                    // Exact (sigma == 0) is not enough: for rank-deficient/structured matrices sigma
                    // shrinks to denormal (nonzero), vtv underflows and beta = 2/vtv OVERFLOWS to Inf,
                    // and the rank-2 update then forms Inf - Inf = NaN. Deflate cleanly before that.
                    if (math.sqrt(sigma) <= belowNormTol)
                    {
                        // column already (effectively) in tridiagonal form
                        eVec[k] = x0;
                        continue;
                    }

                    float xnorm = math.sqrt(x0 * x0 + sigma);
                    float alpha = (x0 >= (float)0) ? -xnorm : xnorm;   // -sign(x0)*||x||

                    // Householder vector v (entries m0..n-1): v[m0] = x0 - alpha, v[i>m0] = x[i].
                    v[m0] = x0 - alpha;
                    for (int i = m0 + 1; i < n; i++) v[i] = ap[(long)i * n + k];

                    float vtv  = v[m0] * v[m0] + sigma;
                    float beta = (float)2 / vtv;

                    // p = beta * A_sub * v   (A_sub = A[m0:n, m0:n], symmetric). Each row dot over the
                    // active column range [m0,n) goes through the SIMD vecDotRange (row and v never alias).
                    for (int r = m0; r < n; r++)
                    {
                        float* arow = ap + (long)r * n;
                        p[r] = beta * UnsafeOP.vecDotRange(arow, v, m0, n);
                    }

                    // K = beta * (vᵀp) / 2;  q = p - K v   (overwrite p with q)
                    float vp = UnsafeOP.vecDotRange(v, p, m0, n);
                    float K = beta * vp / (float)2;
                    for (int i = m0; i < n; i++) p[i] -= K * v[i];

                    // Symmetric rank-2 update: A_sub -= v qᵀ + q vᵀ  (two contiguous axpys per row).
                    int len = n - m0;
                    for (int r = m0; r < n; r++)
                    {
                        float* arow = ap + (long)r * n;
                        UnsafeOP.axpy(arow + m0, p + m0, -v[r], len);   // -= v[r] * q
                        UnsafeOP.axpy(arow + m0, v + m0, -p[r], len);   // -= q[r] * v
                    }

                    eVec[k] = alpha;
                }

                // trailing subdiagonal + diagonal
                eVec[n - 2] = ap[(long)(n - 1) * n + (n - 2)];
                eVec[n - 1] = (float)0;
                for (int i = 0; i < n; i++) eigenvalues[i] = ap[(long)i * n + i];
            }

            // Global tridiagonal scale. The deflation test below is floored by this so a cluster of
            // ZERO eigenvalues can still deflate: there the local |d[m]|+|d[m+1]| collapses to ~0, but
            // the sub-diagonal noise floor is set by the GLOBAL scale, so a purely local threshold
            // never triggers in float and QL spins to maxIter (the rank-deficient values case).
            float anorm = math.abs(eigenvalues[0]) + math.abs(eVec[0]);
            for (int i = 1; i < n; i++)
            {
                float rowSum = math.abs(eVec[i - 1]) + math.abs(eigenvalues[i]) + math.abs(eVec[i]);
                if (rowSum > anorm) anorm = rowSum;
            }

            // ---- implicit-shift QL on the tridiagonal (d = eigenvalues, e), values only ----
            // e[i] couples d[i] and d[i+1]; e[n-1] = 0. sweeps/convergedCount feed EigenInfo: `iter`
            // is the number of QL steps consumed by eigenvalue l (see EigenInfo.sweeps doc comment).
            int sweeps = 0;
            int convergedCount = 0;
            for (int l = 0; l < n; l++)
            {
                int iter = 0;
                int m;
                do
                {
                    for (m = l; m < n - 1; m++)
                    {
                        float dd = math.abs(eigenvalues[m]) + math.abs(eigenvalues[m + 1]);
                        // machine-eps relative, floored by the global scale `anorm` (see above)
                        if (math.abs(eVec[m]) <= (float)8 * Consts.floatEpsilon * (dd + anorm)) break;
                    }
                    if (m != l)
                    {
                        if (iter++ >= maxIterPerEig)
                            return new EigenInfo { status = IterativeSolveStatus.MaxIterations, sweeps = maxIterPerEig, converged = convergedCount };

                        float g = (eigenvalues[l + 1] - eigenvalues[l]) / ((float)2 * eVec[l]);
                        float r = pythag(g, (float)1);
                        g = eigenvalues[m] - eigenvalues[l] + eVec[l] / (g + copysign(r, g));
                        float s = 1, c = 1, pp = 0;
                        int i;
                        for (i = m - 1; i >= l; i--)
                        {
                            float f = s * eVec[i];
                            float b = c * eVec[i];
                            r = pythag(f, g);
                            eVec[i + 1] = r;
                            if (r == (float)0) { eigenvalues[i + 1] -= pp; eVec[m] = 0; break; }
                            s = f / r; c = g / r;
                            g = eigenvalues[i + 1] - pp;
                            r = (eigenvalues[i] - g) * s + (float)2 * c * b;
                            pp = s * r;
                            eigenvalues[i + 1] = g + pp;
                            g = c * r - b;
                        }
                        if (r == (float)0 && i >= l) continue;
                        eigenvalues[l] -= pp; eVec[l] = g; eVec[m] = 0;
                    }
                } while (m != l);

                if (iter > sweeps) sweeps = iter;
                convergedCount++;
            }

            // sort descending (selection sort, matching decompInPlace)
            for (int j = 0; j < n; j++)
            {
                int maxIdx = j;
                float maxVal = eigenvalues[j];
                for (int k = j + 1; k < n; k++)
                    if (eigenvalues[k] > maxVal) { maxIdx = k; maxVal = eigenvalues[k]; }
                if (maxIdx != j)
                {
                    float tmp = eigenvalues[j];
                    eigenvalues[j] = eigenvalues[maxIdx];
                    eigenvalues[maxIdx] = tmp;
                }
            }

            return new EigenInfo { status = IterativeSolveStatus.Converged, sweeps = sweeps, converged = convergedCount };
        }

        /// <summary>valuesSymmetricInPlace (ref workspace) with default maxIterPerEig (Consts.sweepBudget(A.M_Rows)) and tol (Consts.floatZeroThreshold).</summary>
        public static EigenInfo valuesSymmetricInPlace(ref floatMxN A, ref floatN eigenvalues, ref floatEigenSymCache ws)
            => valuesSymmetricInPlace(ref A, ref eigenvalues, Consts.sweepBudget(A.M_Rows), Consts.floatZeroThreshold, ref ws);

        /// <summary>
        /// valuesSymmetricInPlace allocating its tridiagonalization scratch (three length-n vectors) from
        /// Allocator.Temp. See the ref-workspace overload for semantics. A is overwritten (destroyed).
        /// </summary>
        public static EigenInfo valuesSymmetricInPlace(ref floatMxN A, ref floatN eigenvalues, int maxIterPerEig, float tol)
        {
            int n = A.M_Rows;
            var ws = new floatEigenSymCache
            {
                eVec = new floatN(n, Allocator.Temp, false),
                vVec = new floatN(n, Allocator.Temp, false),
                pVec = new floatN(n, Allocator.Temp, false)
            };
            EigenInfo info = valuesSymmetricInPlace(ref A, ref eigenvalues, maxIterPerEig, tol, ref ws);
            ws.eVec.Dispose();
            ws.vVec.Dispose();
            ws.pVec.Dispose();
            return info;
        }

        /// <summary>valuesSymmetricInPlace with default maxIterPerEig (Consts.sweepBudget(A.M_Rows)) and tol (Consts.floatZeroThreshold).</summary>
        public static EigenInfo valuesSymmetricInPlace(ref floatMxN A, ref floatN eigenvalues)
            => valuesSymmetricInPlace(ref A, ref eigenvalues, Consts.sweepBudget(A.M_Rows), Consts.floatZeroThreshold);

        /// <summary>
        /// Full eigenDECOMPOSITION of a SYMMETRIC real matrix via Householder tridiagonalization with
        /// orthogonal accumulation (tred2) + implicit-shift QL with eigenvector accumulation (tql2).
        /// Same result as the cyclic-Jacobi decompInPlace but far faster: the O(n^3)
        /// tridiagonalization is gemv + rank-2 axpy updates (vectorises) and runs ONCE, where Jacobi
        /// does several full sweeps of strided column rotations.
        ///
        /// A must be symmetric (checked within tolerance) and is DESTROYED. On output eigenvalues[i] is the
        /// i-th eigenvalue (sorted DESCENDING) and column i of V is its unit eigenvector, so
        /// A = V * diag(eigenvalues) * Vᵀ and VᵀV = I. Returns an <see cref="EigenInfo"/>
        /// (implicit-bool == Converged); MaxIterations if QL hit maxIterPerEig (outputs then
        /// undefined). Allocates three length-n Temp scratch vectors.
        /// </summary>
        public static EigenInfo symmetricInPlace(ref floatMxN A, ref floatN eigenvalues, ref floatMxN V,
                                          int maxIterPerEig, float tol)
        {
            if (!A.IsSquare)
                throw new ArgumentException("Eigen.symmetricInPlace: A must be square");

            int n = A.M_Rows;

            if (eigenvalues.N != n)
                throw new ArgumentException("Eigen.symmetricInPlace: eigenvalues.N must equal A dimension");

            if (!V.IsSquare || V.M_Rows != n)
                throw new ArgumentException("Eigen.symmetricInPlace: V must be square with side equal to A dimension");

            if (maxIterPerEig < 1)
                throw new ArgumentException("Eigen.symmetricInPlace: maxIterPerEig must be >= 1");

            if (tol <= (float)0)
                throw new ArgumentException("Eigen.symmetricInPlace: tol must be > 0");

            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++)
                {
                    float aij = A[i, j], aji = A[j, i];
                    float diff = math.abs(aij - aji);
                    float relScale = (float)1 + math.abs(aij) + math.abs(aji);
                    if (diff > tol * relScale)
                        throw new ArgumentException("Eigen.symmetricInPlace: Matrix must be symmetric");
                }

            if (n == 0) return new EigenInfo { status = IterativeSolveStatus.Converged, sweeps = 0, converged = 0 };

            // V starts as identity (it accumulates Q = H_0 H_1 ... then the QL rotations).
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    V[i, j] = (i == j) ? (float)1 : (float)0;

            if (n == 1) { eigenvalues[0] = A[0, 0]; return new EigenInfo { status = IterativeSolveStatus.Converged, sweeps = 0, converged = 1 }; }

            var eVec = new floatN(n, Allocator.Temp, false);
            var vVec = new floatN(n, Allocator.Temp, false);
            var pVec = new floatN(n, Allocator.Temp, false);

            // Declared outside the unsafe block: the QL loop below sets these, and the method's
            // final (converged) return reads them after the unsafe block closes.
            int sweepsLocal;
            int convergedLocal;

            unsafe
            {
                float* ap = A.Data.Ptr;
                float* qp = V.Data.Ptr;
                float* v  = vVec.Data.Ptr;
                float* p  = pVec.Data.Ptr;

                // Matrix scale for the deflation test — see valuesSymmetricInPlace.
                float matScale = (float)0;
                for (long ii = 0; ii < (long)n * n; ii++)
                {
                    float a = math.abs(ap[ii]);
                    matScale = math.max(matScale, a);
                }
                float belowNormTol = (float)n * Consts.floatEpsilon * matScale;

                // ---- Householder tridiagonalization with Q accumulation into V ----
                for (int k = 0; k < n - 2; k++)
                {
                    int m0 = k + 1;

                    float sigma = 0;
                    for (int i = m0 + 1; i < n; i++)
                    {
                        float aik = ap[(long)i * n + k];
                        sigma += aik * aik;
                    }
                    float x0 = ap[(long)m0 * n + k];

                    // See valuesSymmetricInPlace: deflate near-negligible columns before vtv underflows
                    // and beta = 2/vtv overflows to Inf (which would make the rank-2 update form NaN).
                    if (math.sqrt(sigma) <= belowNormTol)
                    {
                        eVec[k] = x0;
                        continue;
                    }

                    float xnorm = math.sqrt(x0 * x0 + sigma);
                    float alpha = (x0 >= (float)0) ? -xnorm : xnorm;

                    v[m0] = x0 - alpha;
                    for (int i = m0 + 1; i < n; i++) v[i] = ap[(long)i * n + k];

                    float vtv  = v[m0] * v[m0] + sigma;
                    float beta = (float)2 / vtv;

                    // p = beta * A_sub * v: each row dot over [m0,n) through the SIMD vecDotRange.
                    for (int r = m0; r < n; r++)
                    {
                        float* arow = ap + (long)r * n;
                        p[r] = beta * UnsafeOP.vecDotRange(arow, v, m0, n);
                    }

                    float vp = UnsafeOP.vecDotRange(v, p, m0, n);
                    float K = beta * vp / (float)2;
                    for (int i = m0; i < n; i++) p[i] -= K * v[i];

                    int len = n - m0;
                    for (int r = m0; r < n; r++)
                    {
                        float* arow = ap + (long)r * n;
                        UnsafeOP.axpy(arow + m0, p + m0, -v[r], len);
                        UnsafeOP.axpy(arow + m0, v + m0, -p[r], len);
                    }

                    // Accumulate Q: V := V * H_k  (H_k = I - beta v vᵀ on columns [m0,n)).
                    // For each row r: V[r, m0:] -= beta*(V[r,m0:]·v) * v.
                    for (int r = 0; r < n; r++)
                    {
                        float* qrow = qp + (long)r * n;
                        float s = UnsafeOP.vecDotRange(qrow, v, m0, n);
                        UnsafeOP.axpy(qrow + m0, v + m0, -(beta * s), len);
                    }

                    eVec[k] = alpha;
                }

                eVec[n - 2] = ap[(long)(n - 1) * n + (n - 2)];
                eVec[n - 1] = (float)0;
                for (int i = 0; i < n; i++) eigenvalues[i] = ap[(long)i * n + i];

                // Global tridiagonal scale (see valuesSymmetricInPlace): floors the deflation threshold
                // so clustered zero eigenvalues still deflate instead of spinning QL to maxIter.
                float anorm = math.abs(eigenvalues[0]) + math.abs(eVec[0]);
                for (int i = 1; i < n; i++)
                {
                    float rowSum = math.abs(eVec[i - 1]) + math.abs(eigenvalues[i]) + math.abs(eVec[i]);
                    if (rowSum > anorm) anorm = rowSum;
                }

                // Transpose Q in place so the QL plane rotations below hit CONTIGUOUS rows (unit
                // stride → vectorizes) instead of strided columns. Transposed back after the sweep.
                for (int ti = 0; ti < n; ti++)
                    for (int tj = ti + 1; tj < n; tj++)
                    {
                        float* pa = qp + (long)ti * n + tj;
                        float* pb = qp + (long)tj * n + ti;
                        float t = *pa; *pa = *pb; *pb = t;
                    }

                // ---- implicit-shift QL with eigenvector accumulation (tql2) ----
                // sweeps/convergedCount feed EigenInfo — see valuesSymmetricInPlace's identical convention.
                sweepsLocal = 0;
                convergedLocal = 0;
                for (int l = 0; l < n; l++)
                {
                    int iter = 0;
                    int m;
                    do
                    {
                        for (m = l; m < n - 1; m++)
                        {
                            float dd = math.abs(eigenvalues[m]) + math.abs(eigenvalues[m + 1]);
                            // machine-eps relative, floored by anorm — see valuesSymmetricInPlace.
                            if (math.abs(eVec[m]) <= (float)8 * Consts.floatEpsilon * (dd + anorm)) break;
                        }
                        if (m != l)
                        {
                            if (iter++ >= maxIterPerEig)
                            {
                                eVec.Dispose(); vVec.Dispose(); pVec.Dispose();
                                return new EigenInfo { status = IterativeSolveStatus.MaxIterations, sweeps = maxIterPerEig, converged = convergedLocal };
                            }

                            float g = (eigenvalues[l + 1] - eigenvalues[l]) / ((float)2 * eVec[l]);
                            float r = pythag(g, (float)1);
                            g = eigenvalues[m] - eigenvalues[l] + eVec[l] / (g + copysign(r, g));
                            float s = 1, c = 1, pp = 0;
                            int i;
                            for (i = m - 1; i >= l; i--)
                            {
                                float f = s * eVec[i];
                                float b = c * eVec[i];
                                r = pythag(f, g);
                                eVec[i + 1] = r;
                                if (r == (float)0) { eigenvalues[i + 1] -= pp; eVec[m] = 0; break; }
                                s = f / r; c = g / r;
                                g = eigenvalues[i + 1] - pp;
                                r = (eigenvalues[i] - g) * s + (float)2 * c * b;
                                pp = s * r;
                                eigenvalues[i + 1] = g + pp;
                                g = c * r - b;

                                // Apply the plane rotation to ROWS i, i+1 of the transposed eigenvector
                                // matrix — contiguous + [NoAlias] (distinct rows) so Burst vectorizes it.
                                UnsafeOP.jacobiRotate(qp + (long)i * n, qp + (long)(i + 1) * n, c, s, n);
                            }
                            if (r == (float)0 && i >= l) continue;
                            eigenvalues[l] -= pp; eVec[l] = g; eVec[m] = 0;
                        }
                    } while (m != l);

                    if (iter > sweepsLocal) sweepsLocal = iter;
                    convergedLocal++;
                }

                // Transpose Q back: rows → columns, so column i is eigenvector i again.
                for (int ti = 0; ti < n; ti++)
                    for (int tj = ti + 1; tj < n; tj++)
                    {
                        float* pa = qp + (long)ti * n + tj;
                        float* pb = qp + (long)tj * n + ti;
                        float t = *pa; *pa = *pb; *pb = t;
                    }
            }

            eVec.Dispose();
            vVec.Dispose();
            pVec.Dispose();

            // sort descending by eigenvalue, carrying eigenvector columns along
            for (int j = 0; j < n; j++)
            {
                int maxIdx = j;
                float maxVal = eigenvalues[j];
                for (int k = j + 1; k < n; k++)
                    if (eigenvalues[k] > maxVal) { maxIdx = k; maxVal = eigenvalues[k]; }
                if (maxIdx != j)
                {
                    float tmp = eigenvalues[j];
                    eigenvalues[j] = eigenvalues[maxIdx];
                    eigenvalues[maxIdx] = tmp;
                    Swap.Columns(ref V, j, maxIdx);
                }
            }

            return new EigenInfo { status = IterativeSolveStatus.Converged, sweeps = sweepsLocal, converged = convergedLocal };
        }

        /// <summary>symmetric with default maxIterPerEig (Consts.sweepBudget(A.M_Rows)) and tol (Consts.floatZeroThreshold).</summary>
        public static EigenInfo symmetricInPlace(ref floatMxN A, ref floatN eigenvalues, ref floatMxN V)
            => symmetricInPlace(ref A, ref eigenvalues, ref V, Consts.sweepBudget(A.M_Rows), Consts.floatZeroThreshold);

        /// <summary>
        /// All eigenvalues of a GENERAL (non-symmetric) real square matrix, via the QR algorithm:
        /// reduction to upper Hessenberg form (elimination with partial pivoting) followed by the
        /// Francis double-shift QR iteration to the real Schur form (EISPACK elmhes + hqr). Real
        /// arithmetic only — complex-conjugate eigenvalue pairs are produced from the 2x2 Schur
        /// blocks, so NO complex number type is needed.
        ///
        /// Unlike decompInPlace (symmetric-only Jacobi) and powerIteration (dominant pair only),
        /// this handles arbitrary real matrices including those with complex eigenvalues (e.g.
        /// rotations). It returns eigenVALUES only (no eigenvectors).
        ///
        /// On input A must be square; A is DESTROYED (overwritten during reduction/iteration).
        /// On output eigenvaluesReal[i] / eigenvaluesImag[i] are the real and imaginary parts of the
        /// i-th eigenvalue. Results are sorted by (real, then imaginary) DESCENDING, so a conjugate
        /// pair a±bi appears as (a,+b) immediately before (a,-b). Read the outputs only when the
        /// returned status is Converged.
        ///
        /// Returns an <see cref="EigenInfo"/> (implicit-bool == Converged); Converged iff every
        /// eigenvalue converged within maxIterPerRoot iterations, MaxIterations if the iteration
        /// limit was hit (outputs then undefined). Does not allocate.
        /// </summary>
        public static unsafe EigenInfo valuesQRInPlace(ref floatMxN A, ref floatN eigenvaluesReal,
                                                ref floatN eigenvaluesImag, int maxIterPerRoot)
        {
            if (!A.IsSquare)
                throw new ArgumentException("Eigen.valuesQRInPlace: A must be square");

            int n = A.N_Cols;
            float* ap = A.Data.Ptr;   // row r starts at ap + (long)r * n (square: stride = n)

            if (eigenvaluesReal.N != n)
                throw new ArgumentException("Eigen.valuesQRInPlace: eigenvaluesReal.N must equal A dimension");

            if (eigenvaluesImag.N != n)
                throw new ArgumentException("Eigen.valuesQRInPlace: eigenvaluesImag.N must equal A dimension");

            if (maxIterPerRoot < 1)
                throw new ArgumentException("Eigen.valuesQRInPlace: maxIterPerRoot must be >= 1");

            if (n == 0)
                return new EigenInfo { status = IterativeSolveStatus.Converged, sweeps = 0, converged = 0 };

            // ---- Step 1: reduce A to upper Hessenberg form (elmhes: Gaussian elimination with
            //      partial pivoting via similarity transforms; preserves eigenvalues). ----
            for (int m = 1; m < n - 1; m++)
            {
                // pivot: largest |A[j, m-1]| over rows j >= m.
                float x = (float)0;
                int piv = m;
                for (int j = m; j < n; j++)
                {
                    if (math.abs(A[j, m - 1]) > math.abs(x))
                    {
                        x = A[j, m - 1];
                        piv = j;
                    }
                }

                // interchange rows and columns piv <-> m (a similarity transform).
                if (piv != m)
                {
                    for (int j = m - 1; j < n; j++)
                    {
                        float tmp = A[piv, j]; A[piv, j] = A[m, j]; A[m, j] = tmp;
                    }
                    for (int j = 0; j < n; j++)
                    {
                        float tmp = A[j, piv]; A[j, piv] = A[j, m]; A[j, m] = tmp;
                    }
                }

                // eliminate below the subdiagonal in column m-1.
                if (x != (float)0)
                {
                    for (int i = m + 1; i < n; i++)
                    {
                        float y = A[i, m - 1];
                        if (y != (float)0)
                        {
                            y /= x;
                            A[i, m - 1] = y;                          // store multiplier (cleared below)
                            // row update A[i, m:] -= y * A[m, m:] — unit-stride, vectorized.
                            UnsafeOP.axpy(ap + (long)i * n + m, ap + (long)m * n + m, -y, n - m);
                            // column update A[:, m] += y * A[:, i] — column-strided, left scalar.
                            for (int j = 0; j < n; j++)
                                A[j, m] += y * A[j, i];
                        }
                    }
                }
            }

            // clear the stored multipliers below the subdiagonal -> clean upper Hessenberg H in A.
            for (int i = 2; i < n; i++)
                for (int j = 0; j < i - 1; j++)
                    A[i, j] = (float)0;

            // ---- Step 2: Francis double-shift QR on the Hessenberg matrix (hqr). ----
            float anorm = (float)0;
            for (int i = 0; i < n; i++)
                for (int j = math.max(i - 1, 0); j < n; j++)
                    anorm += math.abs(A[i, j]);

            int nn = n - 1;     // index of the current bottom-right active row/col
            float t = (float)0;

            // sweeps/convergedCount feed EigenInfo: sweeps is the worst `its` seen at any successful
            // root/pair extraction (its is the sweep count hqr itself already tracks per active
            // block -- see maxIterPerRoot's own name/contract); convergedCount tallies extracted
            // eigenvalues (1 per real root, 2 per complex-conjugate pair), reaching n on success.
            int sweeps = 0;
            int convergedCount = 0;

            while (nn >= 0)
            {
                int its = 0;
                int l;
                do
                {
                    // look for a single negligible subdiagonal element to split off.
                    for (l = nn; l >= 1; l--)
                    {
                        float s0 = math.abs(A[l - 1, l - 1]) + math.abs(A[l, l]);
                        if (s0 == (float)0) s0 = anorm;
                        if (math.abs(A[l, l - 1]) + s0 == s0)
                        {
                            A[l, l - 1] = (float)0;
                            break;
                        }
                    }
                    if (l < 0) l = 0;

                    float x = A[nn, nn];

                    if (l == nn)
                    {
                        // one real root.
                        eigenvaluesReal[nn] = x + t;
                        eigenvaluesImag[nn] = (float)0;
                        nn--;
                        if (its > sweeps) sweeps = its;
                        convergedCount++;
                    }
                    else
                    {
                        float y = A[nn - 1, nn - 1];
                        float w = A[nn, nn - 1] * A[nn - 1, nn];

                        if (l == nn - 1)
                        {
                            // two roots from the trailing 2x2 block.
                            float p = (float)0.5 * (y - x);
                            float q = p * p + w;
                            float z = math.sqrt(math.abs(q));
                            x += t;
                            if (q >= (float)0)
                            {
                                // real pair.
                                z = p + copysign(z, p);
                                eigenvaluesReal[nn - 1] = x + z;
                                eigenvaluesReal[nn] = (z != (float)0) ? (x - w / z) : (x + z);
                                eigenvaluesImag[nn - 1] = (float)0;
                                eigenvaluesImag[nn] = (float)0;
                            }
                            else
                            {
                                // complex-conjugate pair a +/- bi.
                                eigenvaluesReal[nn - 1] = x + p;
                                eigenvaluesReal[nn] = x + p;
                                eigenvaluesImag[nn - 1] = z;
                                eigenvaluesImag[nn] = -z;
                            }
                            nn -= 2;
                            if (its > sweeps) sweeps = its;
                            convergedCount += 2;
                        }
                        else
                        {
                            // no root yet: perform a double-shift QR sweep.
                            if (its >= maxIterPerRoot)
                                return new EigenInfo { status = IterativeSolveStatus.MaxIterations, sweeps = maxIterPerRoot, converged = convergedCount };   // not converged

                            if (its == 10 || its == 20)
                            {
                                // exceptional shift to break a cycle.
                                t += x;
                                for (int i = 0; i <= nn; i++)
                                    A[i, i] -= x;
                                float s1 = math.abs(A[nn, nn - 1]) + math.abs(A[nn - 1, nn - 2]);
                                y = x = (float)0.75 * s1;
                                w = (float)(-0.4375) * s1 * s1;
                            }
                            its++;

                            // find two consecutive negligible subdiagonals to start the sweep.
                            float p = (float)0, q = (float)0, r = (float)0;
                            int m;
                            for (m = nn - 2; m >= l; m--)
                            {
                                float z = A[m, m];
                                float rr = x - z;
                                float ss = y - z;
                                p = (rr * ss - w) / A[m + 1, m] + A[m, m + 1];
                                q = A[m + 1, m + 1] - z - rr - ss;
                                r = A[m + 2, m + 1];
                                float s2 = math.abs(p) + math.abs(q) + math.abs(r);
                                // guard the normalization (matches the guarded analog in the QR sweep
                                // below): if p,q,r are all exactly zero, leave them zero rather than
                                // dividing 0/0 -> NaN, which would poison the convergence test.
                                if (s2 != (float)0) { p /= s2; q /= s2; r /= s2; }
                                if (m == l) break;
                                float u = math.abs(A[m, m - 1]) * (math.abs(q) + math.abs(r));
                                float v = math.abs(p) * (math.abs(A[m - 1, m - 1]) + math.abs(z) + math.abs(A[m + 1, m + 1]));
                                if (u + v == v) break;
                            }

                            for (int i = m + 2; i <= nn; i++)
                            {
                                A[i, i - 2] = (float)0;
                                if (i != m + 2) A[i, i - 3] = (float)0;
                            }

                            // the double QR step over rows/cols m..nn.
                            for (int k = m; k <= nn - 1; k++)
                            {
                                if (k != m)
                                {
                                    p = A[k, k - 1];
                                    q = A[k + 1, k - 1];
                                    r = (float)0;
                                    if (k != nn - 1) r = A[k + 2, k - 1];
                                    x = math.abs(p) + math.abs(q) + math.abs(r);
                                    if (x != (float)0)
                                    {
                                        p /= x; q /= x; r /= x;
                                    }
                                }

                                float s = copysign(math.sqrt(p * p + q * q + r * r), p);
                                if (s != (float)0)
                                {
                                    if (k == m)
                                    {
                                        if (l != m)
                                            A[k, k - 1] = -A[k, k - 1];
                                    }
                                    else
                                    {
                                        A[k, k - 1] = -s * x;
                                    }
                                    p += s;
                                    float xx = p / s;
                                    float yy = q / s;
                                    float zz = r / s;
                                    q /= p;
                                    r /= p;

                                    // row modification over columns j = k..nn (unit-stride). Rows
                                    // k, k+1, k+2 are distinct -> [NoAlias] Francis butterfly SIMDs it.
                                    int rowLen = nn - k + 1;
                                    if (k != nn - 1)
                                        UnsafeOP.francisRow3(ap + (long)k * n + k, ap + (long)(k + 1) * n + k,
                                                             ap + (long)(k + 2) * n + k, q, r, xx, yy, zz, rowLen);
                                    else
                                        UnsafeOP.francisRow2(ap + (long)k * n + k, ap + (long)(k + 1) * n + k,
                                                             q, xx, yy, rowLen);

                                    int mmin = nn < k + 3 ? nn : k + 3;
                                    // column modification.
                                    for (int i = l; i <= mmin; i++)
                                    {
                                        p = xx * A[i, k] + yy * A[i, k + 1];
                                        if (k != nn - 1)
                                        {
                                            p += zz * A[i, k + 2];
                                            A[i, k + 2] -= p * r;
                                        }
                                        A[i, k + 1] -= p * q;
                                        A[i, k] -= p;
                                    }
                                }
                            }
                        }
                    }
                } while (l < nn - 1);
            }

            // ---- sort by (real, then imaginary) descending; keep re/im paired. ----
            for (int a = 0; a < n - 1; a++)
            {
                int best = a;
                for (int b = a + 1; b < n; b++)
                {
                    if (eigenvaluesReal[b] > eigenvaluesReal[best] ||
                        (eigenvaluesReal[b] == eigenvaluesReal[best] && eigenvaluesImag[b] > eigenvaluesImag[best]))
                        best = b;
                }
                if (best != a)
                {
                    float tr = eigenvaluesReal[a]; eigenvaluesReal[a] = eigenvaluesReal[best]; eigenvaluesReal[best] = tr;
                    float ti = eigenvaluesImag[a]; eigenvaluesImag[a] = eigenvaluesImag[best]; eigenvaluesImag[best] = ti;
                }
            }

            return new EigenInfo { status = IterativeSolveStatus.Converged, sweeps = sweeps, converged = convergedCount };
        }

        /// <summary>valuesQRInPlace with default maxIterPerRoot (Consts.sweepBudget(A.N_Cols); the EISPACK hqr limit was flat 30).</summary>
        public static EigenInfo valuesQRInPlace(ref floatMxN A, ref floatN eigenvaluesReal,
                                         ref floatN eigenvaluesImag)
            => valuesQRInPlace(ref A, ref eigenvaluesReal, ref eigenvaluesImag, Consts.sweepBudget(A.N_Cols));
    }
}
